class CustomBCLoss(nn.Module):
    """Vanilla NLL loss for GMM behavioral cloning.

    Uses the standard negative log-likelihood loss, identical to the
    default robomimic BC-GMM loss.
    """

    def __init__(self, action_dim=7):
        super().__init__()
        self.action_dim = action_dim

    def forward(self, dist, target_actions):
        return -dist.log_prob(target_actions).mean()
